/**
 * Controller for individual post UI component. Binds Post data to the post.fxml
 * labels.
 */
@Component
@Scope("prototype") // Tells springboot to create individual PostController class for posts
public class PostController {
  private final PostService postService;
  private final UserService userService;

  /** Controller injects the necessary services. */
  @Autowired
  @SuppressFBWarnings(value = "EI_EXPOSE_REP2", justification = "We need to inject the "
      + "userService and postService.")
  public PostController(PostService postService, UserService userService) {
    this.postService = postService;
    this.userService = userService;
  }

  @FXML
  private Label displayNameLabel;
  @FXML
  private Label usernameLabel;
  @FXML
  private Label contentLabel;
  @FXML
  private Button likeBtn;
  @FXML
  private Button retweetBtn;

  @SuppressFBWarnings(value = "EI_EXPOSE_REP2", justification = "The Post is used in a "
      + "tightly scoped controller context where mutation is safe and intentional.")
  private Post currentPost;

  // This JavaDoc comment was generated by Github Copilot
  /** Sets the Post data to the UI labels. */
  // FIXME: BUG! new posts with 0 likes, like button is blue. RECREATE: make new
  // post1 -> like post1 -> make new post2 -> post2 is blue -> make new post3 ->
  // post3 not blue?
  @FXML
  public void setData(Post post) {
    this.currentPost = post;

    displayNameLabel.setText(post.getAuthor().getDisplayName());
    usernameLabel.setText("@" + post.getAuthor().getUsername());
    contentLabel.setText(post.getContent());
    likeBtn.setText(post.getLikes() + " 👍");
    retweetBtn.setText(post.getReTweets() + " 🔄");

    System.out.println("Current user is: " + userService.getLoggedInUser().getUsername());
    if (post.likedByUser(userService.getLoggedInUser())) {
      likeBtn.setStyle("-fx-text-fill: blue;");
    } else {
      likeBtn.setStyle("-fx-text-fill: black;");
    }
    // updateLikes();
    // if (post.reTweetedByUser(userService.getLoggedInUser()))
    // retweetBtn.setStyle("-fx-text-fill: cyan;");
  }

  /** Updates the likes UI elements when the like button is pressed. */
  @FXML
  public void updateLikes() {
    if (currentPost != null) {
      postService.likePost(currentPost, userService.getLoggedInUser());
      postService.update(currentPost);
      likeBtn.setText(currentPost.getLikes() + " 👍");

      System.out.println("2: Current user is: " + userService.getLoggedInUser().getUsername());
      if (currentPost.likedByUser(userService.getLoggedInUser())) {
        likeBtn.setStyle("-fx-text-fill: blue;");
      } else {
        likeBtn.setStyle("-fx-text-fill: black;");
      }
    }
  }

  /** Updates the retweet UI elements when the retweet button is pressed. */
  @FXML
  public void updateRetweets() { // do not remove, posts wont show

  }
}
